SELECT MIN(i_item_id), MIN(s_state), MIN(ss_quantity), MIN(ss_list_price), MIN(ss_coupon_amt), MIN(ss_sales_price), MIN(ss_item_sk), MIN(ss_ticket_number)
FROM store_sales
JOIN (SELECT d_date_sk FROM date_dim WHERE d_year = 1999) d ON store_sales.ss_sold_date_sk = d.d_date_sk
JOIN (SELECT i_item_sk, i_item_id FROM item WHERE i_category = 'Electronics') i ON store_sales.ss_item_sk = i.i_item_sk
JOIN (SELECT s_store_sk, s_state FROM store WHERE s_state = 'IN') s ON store_sales.ss_store_sk = s.s_store_sk
JOIN (SELECT cd_demo_sk FROM customer_demographics WHERE cd_gender = 'F' AND cd_marital_status = 'D' AND cd_education_status = 'College') cd ON store_sales.ss_cdemo_sk = cd.cd_demo_sk
WHERE EXISTS (
  SELECT 1 FROM date_dim d2 WHERE d2.d_date_sk = store_sales.ss_sold_date_sk AND d2.d_year = 1999
) AND EXISTS (
  SELECT 1 FROM item i2 WHERE i2.i_item_sk = store_sales.ss_item_sk AND i2.i_category = 'Electronics'
) AND EXISTS (
  SELECT 1 FROM store s2 WHERE s2.s_store_sk = store_sales.ss_store_sk AND s2.s_state = 'IN'
) AND EXISTS (
  SELECT 1 FROM customer_demographics cd2 WHERE cd2.cd_demo_sk = store_sales.ss_cdemo_sk AND cd2.cd_gender = 'F' AND cd2.cd_marital_status = 'D' AND cd2.cd_education_status = 'College'
);
